//! Test helper for golden fixtures in `tests/golden/` (generated by `tools/golden-harness`).
#![forbid(unsafe_code)]

pub mod deltas;
pub mod great_circle;

use serde_json::Value;
use std::path::PathBuf;

/// One golden case: function name, its arguments and the C# result.
#[derive(Debug, Clone)]
pub struct Case {
    pub func: String,
    pub args: Value,
    pub result: Value,
}

impl Case {
    /// Argument as f64 (accepts the "NaN"/"Infinity" string encoding).
    pub fn f(&self, name: &str) -> f64 {
        num(&self.args[name]).unwrap_or_else(|| panic!("arg {name} missing in {self:?}"))
    }
    /// Argument as string.
    pub fn s(&self, name: &str) -> String {
        self.args[name]
            .as_str()
            .unwrap_or_else(|| panic!("arg {name} not a string in {self:?}"))
            .to_string()
    }
    /// Argument as bool.
    pub fn b(&self, name: &str) -> bool {
        self.args[name]
            .as_bool()
            .unwrap_or_else(|| panic!("arg {name} not a bool in {self:?}"))
    }
    /// Argument as i64.
    pub fn i(&self, name: &str) -> i64 {
        self.args[name]
            .as_i64()
            .unwrap_or_else(|| panic!("arg {name} not an int in {self:?}"))
    }
    /// True if the C# code threw an exception for this case.
    pub fn is_error(&self) -> bool {
        self.result.get("error").is_some()
    }
}

/// A loaded golden fixture file.
#[derive(Debug)]
pub struct Golden {
    pub upstream_commit: String,
    pub cases: Vec<Case>,
}

impl Golden {
    /// All cases for one function name.
    pub fn by_fn<'a>(&'a self, func: &'a str) -> impl Iterator<Item = &'a Case> + 'a {
        self.cases.iter().filter(move |c| c.func == func)
    }
}

/// Repo root (two levels above this crate).
pub fn repo_root() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../..")
        .canonicalize()
        .expect("repo root")
}

/// Load `tests/golden/<name>`.
pub fn load(name: &str) -> Golden {
    let path = repo_root().join("tests/golden").join(name);
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("read {path:?}: {e}"));
    let v: Value = serde_json::from_str(&text).expect("golden json");
    let cases = v["cases"]
        .as_array()
        .expect("cases array")
        .iter()
        .map(|c| Case {
            func: c["fn"].as_str().expect("fn").to_string(),
            args: c["args"].clone(),
            result: c["result"].clone(),
        })
        .collect::<Vec<_>>();
    assert!(!cases.is_empty(), "no cases in {name}");
    Golden {
        upstream_commit: v["upstream_commit"]
            .as_str()
            .unwrap_or_default()
            .to_string(),
        cases,
    }
}

/// Decode a JSON number or the string encodings "NaN", "Infinity", "-Infinity".
pub fn num(v: &Value) -> Option<f64> {
    match v {
        Value::Number(n) => n.as_f64(),
        Value::String(s) => match s.as_str() {
            "NaN" => Some(f64::NAN),
            "Infinity" => Some(f64::INFINITY),
            "-Infinity" => Some(f64::NEG_INFINITY),
            _ => None,
        },
        _ => None,
    }
}

/// Assert two floats are equal within `tol` (NaN == NaN, inf == inf of same sign).
#[track_caller]
pub fn assert_close(actual: f64, expected: f64, tol: f64, ctx: &dyn std::fmt::Debug) {
    let ok = (actual.is_nan() && expected.is_nan())
        || actual == expected
        || (actual - expected).abs() <= tol;
    assert!(
        ok,
        "mismatch: actual {actual:?} expected {expected:?} (tol {tol}) for {ctx:?}"
    );
}

/// Assert `actual` matches the golden JSON value `expected` (number or encoded string).
#[track_caller]
pub fn assert_close_v(actual: f64, expected: &Value, tol: f64, ctx: &dyn std::fmt::Debug) {
    let e = num(expected)
        .unwrap_or_else(|| panic!("golden result not a number: {expected:?} for {ctx:?}"));
    assert_close(actual, e, tol, ctx);
}
